--PR-45947 Rohit on 14-DEC-10 removed hint --+ ordered full(w) parallel(w, 2) -- Rohit on 15/07/10 for PR 44564:ADDED TRUSTED PAIR FUNCTIONALITY --PR41512: Added jurisdiction filter, changed verification that ORIG and BENEF are not identical and SCND_ORIG and BENEF are not identical -- -------------------------------------------------------------------------------------------------------- --BENEF -- -------------------------------------------------------------------------------------------------------- select a.PRMRY_CUST_INTRL_ID, w.FO_TRXN_SEQ_ID, w.BENEF_ACTVY_RISK_NB as ACTVY_RISK_NB , case when w.BENEF_ACTVY_RISK_NB>=@Min_Very_High_Risk_Lvl then 'VHRT' when w.BENEF_ACTVY_RISK_NB>=@Min_High_Risk_Lvl and w.BENEF_ACTVY_RISK_NB<@Min_Very_High_Risk_Lvl then 'HRT' end as Trans_Ty
from @BUSINESS@.WIRE_TRXN w inner join @BUSINESS@.ACCT a on w.BENEF_ACCT_ID = a.ACCT_INTRL_ID -- Removing the below section and replacing with an exist clause --left outer join @BUSINESS@.ACCT a1 on (w.ORIG_ACCT_ID = a1.ACCT_INTRL_ID or w.SCND_ORIG_ACCT_ID = a1.ACCT_INTRL_ID) /* inner join @MANTAS@.KDD_CAL b on w.TRXN_EXCTN_DT <= b.CLNDR_DT and w.TRXN_EXCTN_DT > add_days(b.CLNDR_DT, - @Look_Back_Period) and b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0*/ where w.INTRL_BENEF_ACCT_FL = 'Y' -- PR41512 --Replace this filter with an exists clause on ORIG only, SCND_ORIG taken care of in another UNION ALL --and (a1.PRMRY_CUST_INTRL_ID is null or (a1.PRMRY_CUST_INTRL_ID is not null and a1.PRMRY_CUST_INTRL_ID <> a.PRMRY_CUST_INTRL_ID)) and not exists ( select 1 from @BUSINESS@.acct a1 where a1.acct_intrl_id = w.orig_acct_id and a1.prmry_cust_intrl_id = a.prmry_cust_intrl_id and w.INTRL_ORIG_ACCT_FL = 'Y' and a1.MANTAS_ACCT_BUS_TYPE_CD IN (@Mantas_Bus_Acct_Type_Lst) and a1.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR'
) and not exists ( select 1 from @BUSINESS@.acct a2 where a2.acct_intrl_id = w.scnd_orig_acct_id and a2.prmry_cust_intrl_id = a.prmry_cust_intrl_id and w.INTRL_SCND_ORIG_ACCT_FL = 'Y' and a2.MANTAS_ACCT_BUS_TYPE_CD IN (@Mantas_Bus_Acct_Type_Lst) and a2.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR' ) and (@All_Trans_Src_Fl = 'Y' or w.SRC_SYS_CD IN (@Incl_Trans_Src_Lst)) and a.MANTAS_ACCT_BUS_TYPE_CD IN (@Mantas_Bus_Acct_Type_Lst) and a.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR' and w.MANTAS_TRXN_PRDCT_CD in (@Incl_Wire_Trxn_Prdct_Type_Lst) and w.MANTAS_TRXN_PURP_CD = 'GENERAL' and a.PRMRY_CUST_INTRL_ID is not null and (@Incl_Rltd_Parties ='Y' or COALESCE (w.UNRLTD_PARTY_FL,'Y') <>'N') and w.CXL_PAIR_TRXN_INTRL_ID is null and w.TRXN_EXCTN_DT <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.TRXN_EXCTN_DT > (select add_days(b.CLNDR_DT, - @Look_Back_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT > (select add_days(b.CLNDR_DT, - @Look_Back_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) -- additional filter: this dataset using to bind either HR or VHR transactions and has no interest in rest of transactions and w.BENEF_ACTVY_RISK_NB>=@Min_High_Risk_Lvl --PR41512 -- Filter out accounts for the required jurisdiction and exists (select 1 from @BUSINESS@.cust c where c.cust_intrl_id = a.prmry_cust_intrl_id and (@All_Jurisdictions_Fl = 'Y' or c.JRSDCN_CD in (@Incl_Jurisdictions_Lst))) --PR44564 --ADDED TRUSTED PAIR FUNCTIONALITY and (@Include_Trusted_Trans_FL = 'Y' or COALESCE(w.TRSTD_TRXN_FL,'N') ='N')

-- Rohit on 15/07/10 for PR 44564:ADDED TRUSTED PAIR FUNCTIONALITY --PR41512: Added jurisdiction filter, changed verification that ORIG and SCND BENEF are not identical , SCND_ORIG and SCND BENEF are not identical and -- BENEF and SCND BENEF are not identical -- -------------------------------------------------------------------------------------------------------- --SCND_BENEF -- -------------------------------------------------------------------------------------------------------- select --+ full(w) parallel(w, 2) a.PRMRY_CUST_INTRL_ID, w.FO_TRXN_SEQ_ID , w.SCND_BENEF_ACTVY_RISK_NB as ACTVY_RISK_NB , case when w.SCND_BENEF_ACTVY_RISK_NB>=@Min_Very_High_Risk_Lvl then 'VHRT' when w.SCND_BENEF_ACTVY_RISK_NB>=@Min_High_Risk_Lvl and w.SCND_BENEF_ACTVY_RISK_NB<@Min_Very_High_Risk_Lvl then 'HRT' end as Trans_Ty
from @BUSINESS@.WIRE_TRXN w inner join @BUSINESS@.ACCT a on w.SCND_BENEF_ACCT_ID = a.ACCT_INTRL_ID -- Removing the below section and replacing with an exist clause --@BUSINESS@.ACCT a1 on w.BENEF_ACCT_ID = a1.ACCT_INTRL_ID --left outer join @BUSINESS@.ACCT a2 on (w.ORIG_ACCT_ID = a2.ACCT_INTRL_ID or w.SCND_ORIG_ACCT_ID = a2.ACCT_INTRL_ID) where w.INTRL_SCND_BENEF_ACCT_FL = 'Y' --PR41512 Replacing the below condition using exists clause for correct results, checks ORIG and SCND_ORIG --and (a2.PRMRY_CUST_INTRL_ID is null or (a2.PRMRY_CUST_INTRL_ID is not null and a2.PRMRY_CUST_INTRL_ID <> a.PRMRY_CUST_INTRL_ID)) and not exists ( select 1 from @BUSINESS@.acct a1 where a1.acct_intrl_id = w.orig_acct_id and a1.prmry_cust_intrl_id = a.prmry_cust_intrl_id and w.INTRL_ORIG_ACCT_FL = 'Y' and a1.MANTAS_ACCT_BUS_TYPE_CD IN (@Mantas_Bus_Acct_Type_Lst) and a1.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR'
) and not exists ( select 1 from @BUSINESS@.acct a2 where a2.acct_intrl_id = w.scnd_orig_acct_id and a2.prmry_cust_intrl_id = a.prmry_cust_intrl_id and w.INTRL_SCND_ORIG_ACCT_FL = 'Y' and a2.MANTAS_ACCT_BUS_TYPE_CD IN (@Mantas_Bus_Acct_Type_Lst) and a2.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR'
) --- Checking whether the SCND_BENEF is not the same customer as BENEF and not exists ( select 1 from @BUSINESS@.acct a3 where a3.acct_intrl_id = w.benef_acct_id and a3.prmry_cust_intrl_id = a.prmry_cust_intrl_id and w.INTRL_BENEF_ACCT_FL = 'Y' and a3.MANTAS_ACCT_BUS_TYPE_CD IN (@Mantas_Bus_Acct_Type_Lst) and a3.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR'
)
and w.MANTAS_TRXN_PRDCT_CD in (@Incl_Wire_Trxn_Prdct_Type_Lst) and w.MANTAS_TRXN_PURP_CD = 'GENERAL' and (@All_Trans_Src_Fl = 'Y' or w.SRC_SYS_CD IN (@Incl_Trans_Src_Lst)) --and ((w.INTRL_BENEF_ACCT_FL = 'Y' and a1.prmry_cust_intrl_id <> a.prmry_cust_intrl_id) or w.INTRL_BENEF_ACCT_FL <> 'Y') and a.prmry_cust_intrl_id is not null -- and a1.prmry_cust_intrl_id is not null and a.MANTAS_ACCT_BUS_TYPE_CD IN (@Mantas_Bus_Acct_Type_Lst) --and a1.MANTAS_ACCT_BUS_TYPE_CD IN (@Mantas_Bus_Acct_Type_Lst) and a.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR' --and a1.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR' and (@Incl_Rltd_Parties ='Y' or COALESCE (w.UNRLTD_PARTY_FL,'Y') <>'N') and w.CXL_PAIR_TRXN_INTRL_ID is null and w.TRXN_EXCTN_DT <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.TRXN_EXCTN_DT > (select add_days(b.CLNDR_DT, - @Look_Back_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) and w.DATA_DUMP_DT > (select add_days(b.CLNDR_DT, - @Look_Back_Period) from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.CLNDR_DAY_AGE = 0) -- additional filter: this dataset using to bind either HR or VHR transactions and has no interest in rest of transactions and w.SCND_BENEF_ACTVY_RISK_NB>=@Min_High_Risk_Lvl --PR44564 --ADDED TRUSTED PAIR FUNCTIONALITY and (@Include_Trusted_Trans_FL = 'Y' or COALESCE(w.TRSTD_TRXN_FL,'N') ='N')
